\coordinate (E4) at (4.8,0.6);
\coordinate (E5) at (4.8,0);
\coordinate (E6) at (4.8,-0.6);
\coordinate (E7) at (4.8,-1.2);
\coordinate (E8) at (4.8,-1.8);
\coordinate (E9) at (4.8,-2.4);
\draw (O) -- (N1) node[midway, above, fill=white, font=\small] {$\frac{1}{3}$};
\draw (O) -- (N2) node[midway, fill=white, font=\small] {$\frac{1}{3}$};
\draw (O) -- (N3) node[midway, below, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N1) -- (E1) node[midway, above, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N1) -- (E2) node[midway, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N1) -- (E3) node[midway, below, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N2) -- (E4) node[midway, above, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N2) -- (E5) node[midway, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N2) -- (E6) node[midway, below, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N3) -- (E7) node[midway, above, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N3) -- (E8) node[midway, fill=white, font=\small] {$\frac{1}{3}$};
\draw (N3) -- (E9) node[midway, below, fill=white, font=\small] {$\frac{1}{3}$};
\node[fill=white, inner sep=1pt] at (N1) {$R$};
\node[fill=white, inner sep=1pt] at (N2) {$G$};
\node[fill=white, inner sep=1pt] at (N3) {$B$};
\node[right, font=\small] at (E1) {$R$};
\node[right, font=\small] at (E2) {$G$};
\node[right, font=\small] at (E3) {$B$};
\node[right, font=\small] at (E4) {$R$};
\node[right, font=\small] at (E5) {$G$};
\node[right, font=\small] at (E6) {$B$};
\node[right, font=\small] at (E7) {$R$};
\node[right, font=\small] at (E8) {$G$};
\node[right, font=\small] at (E9) {$B$};
\end{tikzpicture}
[/tikz]
Find the probability of spinning two matching colours, as a fraction in simplest form.

development.question_text:
Two archers shoot at a target independently.
Archer A hits the bullseye with probability $0.7$, while Archer B hits the bullseye with probability $0.6$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.95]
\coordinate (O) at (0,0);
\coordinate (N1) at (2.4,1.4);
\coordinate (N2) at (2.4,-1.4);
\coordinate (E1) at (5.0,2.2);
\coordinate (E2) at (5.0,0.6);
\coordinate (E3) at (5.0,-0.6);
\coordinate (E4) at (5.0,-2.2);
\draw (O) -- (N1) node[midway, above, fill=white, font=\small] {$0.7$};
\draw (O) -- (N2) node[midway, below, fill=white, font=\small] {$0.3$};
\draw (N1) -- (E1) node[midway, above, fill=white, font=\small] {$0.6$};
\draw (N1) -- (E2) node[midway, below, fill=white, font=\small] {$0.4$};
\draw (N2) -- (E3) node[midway, above, fill=white, font=\small] {$0.6$};
\draw (N2) -- (E4) node[midway, below, fill=white, font=\small] {$0.4$};
\node[fill=white, inner sep=2pt] at (N1) {$H_{A}$};
\node[fill=white, inner sep=2pt] at (N2) {$M_{A}$};
\node[right] at (E1) {$H_{B}$};
\node[right] at (E2) {$M_{B}$};
\node[right] at (E3) {$H_{B}$};
\node[right] at (E4) {$M_{B}$};
\end{tikzpicture}
[/tikz]
Find the probability that exactly one of the archers hits the bullseye, as a decimal.
